import json

def evaluate():
    with open('/app/data/possible_solutions.json', 'r') as f:
        solutions = json.load(f)

    results = {}

    # Oscillation detected: 65002 prefers 65003, 65003 prefers 65002.
    # To resolve: break the cycle.

    # Route leak detected: 65002 advertises 65001 (provider) to 65003 (peer).
    # To resolve: stop 65002 from advertising 65001 routes to 65003.

    for sol in solutions:
        osc_res = False
        leak_res = False

        # Oscillation resolution logic
        if "Update routing preference on hub1 (ASN 65002) to stop preferring routes via hub2 (ASN 65003)" in sol:
            osc_res = True
        if "disable hub peering between vhubvnet1 and vhubvnet2" in sol:
            osc_res = True
            leak_res = True
        if "Enable Virtual WAN hub routing intent" in sol:
            osc_res = True
            leak_res = True
        if "Set route preference hierarchy on hub1: customer routes (VNET1, VNET2) > Virtual WAN routes > peer routes (vhubvnet2)" in sol:
            osc_res = True

        # Route leak resolution logic
        if "Configure route policy on vhubvnet1 to enforce no-export of provider routes to peer vhubvnet2" in sol:
            leak_res = True
        if "Configure export policy on vhubvnet1 (ASN 65002) to block announcing provider routes (from Virtual WAN ASN 65001) to peer vhubvnet2 (ASN 65003)" in sol:
            leak_res = True

        results[sol] = {
            "oscillation_resolved": osc_res,
            "route_leak_resolved": leak_res
        }

    report = {
        "oscillation_detected": True,
        "oscillation_cycle": [65002, 65003],
        "affected_ases": [65002, 65003],
        "route_leak_detected": True,
        "route_leaks": [
            {
                "leaker_as": 65002,
                "source_as": 65001,
                "destination_as": 65003,
                "source_type": "provider",
                "destination_type": "peer"
            }
        ],
        "solution_results": results
    }

    with open('/app/output/oscillation_report.json', 'w') as f:
        json.dump(report, f, indent=2)

if __name__ == "__main__":
    evaluate()
